// The docs site: a sidebar, a search box and one page per component, foundation,
// pattern and screen. Every page is drawn from window.DS (data.js, generated by
// scripts/build-design-site.mjs). Live examples come from the design system's own
// inventory page, loaded once in an iframe and narrowed to one component at a time.
(function () {
  const DS = window.DS;
  const $ = (id) => document.getElementById(id);
  const top = $('view-top');
  const bottom = $('view-bottom');
  const example = $('example');
  const inventory = $('inventory');
  const nav = $('nav');
  const search = $('search');
  const side = $('side');
  const menu = $('menu');

  const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
  const md = (text) => (window.marked ? window.marked.parse(text) : `<pre>${esc(text)}</pre>`);
  const groupOf = (id) => DS.groups.find((g) => g.id === id);
  const inGroup = (id) => DS.components.filter((c) => c.group === id);

  // Every page, keyed by the bare word after # in the address.
  const pages = new Map();
  pages.set('home', { title: 'Overview', render: home });
  pages.set('guidelines', { title: 'Written guidelines', render: guidelines });
  DS.foundations.forEach((f) => pages.set(f.id, { title: f.name, render: () => foundation(f) }));
  DS.groups.forEach((g) => pages.set(g.id, { title: g.name, render: () => group(g) }));
  DS.patterns.forEach((p) => pages.set(p.id, { title: p.name, render: () => pattern(p) }));
  DS.screens.forEach((s) => pages.set(s.id, { title: s.name, render: () => screen(s) }));
  DS.components.forEach((c) => pages.set(pages.has(c.id) ? `component-${c.id}` : c.id, { title: c.name, component: c, render: () => component(c) }));
  const hrefFor = (c) => `#${[...pages].find(([, p]) => p.component === c)[0]}`;

  // ---- Sidebar -------------------------------------------------------------

  function link(href, label, count) {
    return `<a class="ds-nav__link" href="${href}"><span>${esc(label)}</span>${count != null ? `<b>${count}</b>` : ''}</a>`;
  }

  function drawNav() {
    const q = search.value.trim().toLowerCase();
    if (q) {
      const hits = [];
      DS.components.forEach((c) => {
        const hay = `${c.name} ${c.also.join(' ')} ${c.summary}`.toLowerCase();
        if (hay.includes(q)) hits.push({ href: hrefFor(c), label: c.name, rank: c.name.toLowerCase().startsWith(q) ? 0 : 1 });
      });
      [...DS.foundations, ...DS.patterns, ...DS.screens].forEach((p) => {
        if (`${p.name} ${p.subtitle || ''}`.toLowerCase().includes(q)) hits.push({ href: `#${p.id}`, label: p.name, rank: 2 });
      });
      hits.sort((a, b) => a.rank - b.rank || a.label.localeCompare(b.label));
      nav.innerHTML = hits.length
        ? hits.map((h) => link(h.href, h.label)).join('')
        : `<p class="ds-nav__empty">Nothing matches "${esc(search.value)}".</p>`;
      markCurrent();
      return;
    }
    const current = pages.get(route());
    const openGroup = current?.component?.group || (groupOf(route()) && route());
    nav.innerHTML = [
      link('#home', 'Overview'),
      link('#guidelines', 'Written guidelines'),
      '<div class="ds-nav__label">Foundations</div>',
      ...DS.foundations.map((f) => link(`#${f.id}`, f.name)),
      '<div class="ds-nav__label">Components</div>',
      ...DS.groups.map((g) => `
        <details class="ds-nav__group"${g.id === openGroup ? ' open' : ''}>
          <summary>${link(`#${g.id}`, g.name, inGroup(g.id).length)}</summary>
          <div class="ds-nav__sub">${inGroup(g.id).map((c) => link(hrefFor(c), c.name)).join('')}</div>
        </details>`),
      '<div class="ds-nav__label">Patterns</div>',
      ...DS.patterns.map((p) => link(`#${p.id}`, p.name)),
      '<div class="ds-nav__label">Screens</div>',
      ...DS.screens.map((s) => link(`#${s.id}`, s.name)),
    ].join('');
    // A group's own name both opens it and goes to its page.
    nav.querySelectorAll('.ds-nav__group > summary').forEach((s) => {
      s.addEventListener('click', (e) => {
        e.preventDefault();
        location.hash = s.querySelector('a').getAttribute('href');
      });
    });
    markCurrent();
  }

  function markCurrent() {
    const here = `#${route()}`;
    nav.querySelectorAll('.ds-nav__link').forEach((a) => {
      if (a.getAttribute('href') === here) a.setAttribute('aria-current', 'page');
      else a.removeAttribute('aria-current');
    });
  }

  // ---- Shared pieces -------------------------------------------------------

  function title(h1, lede, extra = '') {
    return `<div class="ds-title"><h1>${esc(h1)}</h1>${lede ? `<p>${lede}</p>` : ''}${extra}</div>`;
  }

  function cardPanel(c, opts = {}) {
    const height = opts.height || c.h;
    return `
      <figure class="ds-panel${opts.screen ? ' ds-screen' : ''}" style="margin:0">
        <figcaption class="ds-panel__head">
          <div><h3>${esc(opts.name || c.name)}</h3>${c.subtitle ? `<p>${esc(c.subtitle)}</p>` : ''}</div>
          <div class="ds-links"><a href="${esc(c.path)}" target="_blank" rel="noopener">Open on its own</a></div>
        </figcaption>
        <div class="ds-panel__frame"><iframe src="${esc(c.path)}" title="${esc(opts.name || c.name)}" loading="lazy" style="height:${height}px"></iframe></div>
      </figure>`;
  }

  function tiles(list, small) {
    return `<div class="ds-tiles${small ? ' ds-tiles--small' : ''}">${list.map((t) => `
      <a class="ds-tile" href="${t.href}"><strong>${esc(t.name)}${t.count != null ? `<b>${t.count}</b>` : ''}</strong><span>${esc(t.text)}</span></a>`).join('')}</div>`;
  }

  // ---- Pages ---------------------------------------------------------------

  function home() {
    const first = DS.groups[0];
    top.innerHTML = `
      ${title('BlueWorx Admin Design System', 'How every BlueWorx plugin\'s admin screens look and behave: one accent, one type pairing, one control size, one panel. Everything here is the real stylesheet and components, drawn live.')}
      ${tiles([
        { href: `#${first.id}`, name: 'Components', count: DS.components.length, text: 'Every building block, each with a live example, how to use it and its options.' },
        { href: `#${DS.foundations[0].id}`, name: 'Foundations', text: 'Colour, type, spacing, corners, shadows, motion and icons.' },
        { href: `#${DS.patterns[0].id}`, name: 'Patterns', count: DS.patterns.length, text: 'Bigger arrangements: calendars, compare tables and settings screens.' },
        { href: `#${DS.screens[0].id}`, name: 'Screens', count: DS.screens.length, text: 'Whole click-through screens inside real WordPress chrome.' },
        { href: '#guidelines', name: 'Written guidelines', text: 'Voice, rules and which control to use for which job.' },
      ])}
      <section><h2 class="ds-h2">Components by group</h2>
        ${tiles(DS.groups.map((g) => ({ href: `#${g.id}`, name: g.name, count: inGroup(g.id).length, text: g.what })))}
      </section>`;
  }

  function guidelines() {
    top.innerHTML = `<article class="ds-prose">${md(DS.guidelines)}</article>`;
  }

  function foundation(f) {
    top.innerHTML = `${title(f.name)}${f.cards.map((c) => cardPanel(c)).join('')}`;
  }

  function group(g) {
    const sheets = DS.sheets[g.id] || [];
    top.innerHTML = `
      ${title(g.name, esc(g.what))}
      ${tiles(inGroup(g.id).map((c) => ({ href: hrefFor(c), name: c.name, text: c.summary })), true)}
      ${sheets.length ? `<section style="display:flex;flex-direction:column;gap:16px"><h2 class="ds-h2" style="margin:0">The whole group together</h2>${sheets.map((c) => cardPanel(c)).join('')}</section>` : ''}`;
  }

  function pattern(p) {
    top.innerHTML = `${title(p.name, esc(p.subtitle))}${cardPanel(p.card, { name: p.name })}`;
  }

  function screen(s) {
    top.innerHTML = `${title(s.name, esc(s.subtitle))}${cardPanel({ path: s.path, name: s.name }, { screen: true, height: 820 })}`;
  }

  function component(c) {
    const g = groupOf(c.group);
    const also = c.also.length ? `<p class="ds-also">Also in this file: ${c.also.map((a) => `<code>${esc(a)}</code>`).join(', ')}</p>` : '';
    top.innerHTML = `
      <div class="ds-crumb"><a href="#${g.id}">${esc(g.name)}</a><span>/</span><span>${esc(c.name)}</span></div>
      ${title(c.name, esc(c.summary), also)}
      <div class="ds-links"><a href="${DS.sourceBase}${esc(c.source)}" target="_blank" rel="noopener">Source on GitHub</a><a href="#${g.id}">More in ${esc(g.name)}</a></div>`;

    let body = '';
    if (c.example?.kind === 'card') body += cardPanel({ path: c.example.path, name: `${c.name} in use` }, { height: c.example.h });
    if (!c.example) body += '<p class="ds-title"><span style="color:var(--bw-text-muted)">No live example yet.</span></p>';
    if (c.guide) body += `<section><h2 class="ds-h2">How to use it</h2><div class="ds-prose">${md(c.guide)}</div></section>`;
    if (c.types.length) body += `<section><h2 class="ds-h2">Options</h2>${options(c)}</section>`;
    bottom.innerHTML = body;

    if (c.example?.kind === 'inventory') {
      example.hidden = false;
      focusExample(c.example.label, c.name);
    }
  }

  function options(c) {
    const main = c.types.filter((t) => t.name.endsWith('Props'));
    const shapes = c.types.filter((t) => !t.name.endsWith('Props'));
    const table = (t) => t.fields.length ? `
      <div class="ds-panel ds-props-wrap"><table class="ds-props">
        <thead><tr><th>Option</th><th>Takes</th><th>What it does</th></tr></thead>
        <tbody>${t.fields.map((f) => `<tr><td>${esc(f.name)}${f.required ? '<span class="ds-req">required</span>' : ''}</td><td><code>${esc(f.type)}</code></td><td>${esc(f.note)}</td></tr>`).join('')}</tbody>
      </table></div>` : '';
    const block = (t, heading) => `
      <div class="ds-shape">
        ${heading ? `<h3>${esc(t.name.replace(/Props$/, ''))}</h3>` : ''}
        ${t.doc ? `<p>${esc(t.doc)}</p>` : ''}
        ${table(t)}
      </div>`;
    return main.map((t) => block(t, main.length > 1)).join('')
      + (shapes.length ? `<h3 class="ds-h2" style="font-size:15px;margin-top:24px">Shapes it takes</h3>${shapes.map((t) => block(t, true)).join('')}` : '');
  }

  // ---- Live examples -------------------------------------------------------

  // Overlays open inside the frame, so these need room to show.
  const ROOM = { Modal: 460, Drawer: 560, Toast: 200, DropdownMenu: 300, Tooltip: 130, HelpTip: 160 };
  let watching = null;

  function focusExample(label, name) {
    const doc = inventory.contentDocument;
    const ready = doc && doc.querySelector('.item');
    if (!ready) {
      setTimeout(() => { if (pages.get(route())?.component?.name === name) focusExample(label, name); }, 120);
      return;
    }
    if (!doc.getElementById('ds-focus')) {
      const style = doc.createElement('style');
      style.id = 'ds-focus';
      style.textContent = 'html,body{background:#fff!important}.inv{padding:0!important;max-width:none!important}'
        + '.inv__head,.jump,.grp__bar,.item__head,.item__props{display:none!important}.grp{margin:0!important}'
        + '.items{display:block!important}.item{border:0!important;box-shadow:none!important;border-radius:0!important}'
        + '.item__demo{padding:24px!important}.ds-off{display:none!important}';
      doc.head.appendChild(style);
    }
    doc.querySelectorAll('.item').forEach((it) => {
      it.classList.toggle('ds-off', it.querySelector('.item__name')?.textContent.trim() !== label);
    });
    doc.querySelectorAll('.grp').forEach((g) => g.classList.toggle('ds-off', !g.querySelector('.item:not(.ds-off)')));
    const fit = () => {
      const h = doc.querySelector('.inv')?.getBoundingClientRect().height || 0;
      inventory.style.height = `${Math.max(Math.ceil(h), ROOM[name] || 0, 80)}px`;
    };
    fit();
    if (watching) watching.disconnect();
    watching = new (inventory.contentWindow.ResizeObserver || ResizeObserver)(fit);
    watching.observe(doc.querySelector('.inv'));
  }

  // ---- Routing -------------------------------------------------------------

  function route() {
    const h = location.hash.slice(1);
    return pages.has(h) ? h : 'home';
  }

  function show() {
    const id = route();
    const page = pages.get(id);
    example.hidden = true;
    top.innerHTML = '';
    bottom.innerHTML = '';
    page.render();
    document.title = id === 'home' ? 'BlueWorx Admin Design System' : `${page.title} · BlueWorx Admin Design System`;
    drawNav();
    side.classList.remove('is-open');
    menu.setAttribute('aria-expanded', 'false');
    window.scrollTo(0, 0);
  }

  // ---- Wiring --------------------------------------------------------------

  search.addEventListener('input', drawNav);
  search.addEventListener('keydown', (e) => {
    if (e.key === 'Enter') {
      const first = nav.querySelector('.ds-nav__link');
      if (first) { location.hash = first.getAttribute('href'); search.value = ''; drawNav(); }
    }
    if (e.key === 'Escape') { search.value = ''; drawNav(); }
  });
  document.addEventListener('keydown', (e) => {
    const typing = /input|textarea|select/i.test(document.activeElement?.tagName || '');
    if (e.key === '/' && !typing) { e.preventDefault(); side.classList.add('is-open'); search.focus(); }
  });
  menu.addEventListener('click', () => {
    const open = side.classList.toggle('is-open');
    menu.setAttribute('aria-expanded', String(open));
  });
  window.addEventListener('hashchange', show);

  $('foot').innerHTML = `Built ${esc(DS.built)}${DS.commit ? ` from <a href="${DS.repo}/commit/${esc(DS.commit)}">${esc(DS.commit)}</a>` : ''}. The design system folder in <a href="${DS.repo}">bluegroup_core_foundation</a> is the source; this site and the Claude Design project are copies of it.`;
  show();
})();
